AZADA","residual":"","diferencias":"Complementa contrato publicado cuando corresponde; cobertura de superficies activas vinculadas, sin modificar pagos ni decisiones pendientes. Contrato completo parametrizado."}],"paquete":{"tipo":"NUEVA","codigo":"S22AL-358-1","clave":"s22al_legacy_358_0","familia":"FEATURE_FLAGS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Insignias/hitos de gamificación: opcionales y desactivables sin penalización","descripcion":"BLOQUEAR incumplimiento: Toda insignia, racha o hito de gamificación (incluido el hito final Recupera con gold_reward) debe poder desactivarse u ocultarse por el usuario sin ninguna penalización financiera ni funcional. Si existe mecánica de racha, debe permitir congelamiento por única vez en caso de emergencia. Referencias literales del contrato fuente: {\"fuente\":\"ACT-0017\",\"badges_desactivables\":true,\"penalizacion_por_desactivar\":\"ninguna\",\"racha_congelamiento_emergencia\":\"una_vez\"}. Parámetros public.lf_global_config: CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT. Complementa S22J-C05. Binding runtime pendiente; no modifica obligaciones de pago ni activa funcionalidades.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/358","solicitante":"Cristhian / Claude S22-AL"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"al_gamification"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"al_cannot_hide_or_disable"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"al_financial_penalty"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"al_functional_penalty"},"der":{"lit":true}}},"der":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"al_streak_exists"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"al_emergency"},"der":{"lit":true}}},"der":{"op":"o","izq":{"op":"y","izq":{"op":"<","izq":{"hecho":"al_freeze_count"},"der":{"param":"CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT"}},"der":{"op":"=","izq":{"hecho":"al_freeze_denied"},"der":{"lit":true}}},"der":{"op":"y","izq":{"op":">=","izq":{"hecho":"al_freeze_count"},"der":{"param":"CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT"}},"der":{"op":"=","izq":{"hecho":"al_excess_freeze_allowed"},"der":{"lit":true}}}}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"al_gamification":true,"al_cannot_hide_or_disable":false,"al_financial_penalty":false,"al_functional_penalty":false,"al_streak_exists":true,"al_emergency":true,"al_freeze_count":{"param":"CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT","mas":0},"al_freeze_denied":false,"al_excess_freeze_allowed":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"al_gamification":true,"al_cannot_hide_or_disable":true,"al_financial_penalty":false,"al_functional_penalty":false,"al_streak_exists":true,"al_emergency":true,"al_freeze_count":{"param":"CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT","mas":0},"al_freeze_denied":false,"al_excess_freeze_allowed":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"al_gamification":true,"al_cannot_hide_or_disable":false,"al_financial_penalty":true,"al_functional_penalty":false,"al_streak_exists":true,"al_emergency":true,"al_freeze_count":{"param":"CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT","mas":0},"al_freeze_denied":false,"al_excess_freeze_allowed":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"al_gamification":true,"al_cannot_hide_or_disable":false,"al_financial_penalty":false,"al_functional_penalty":true,"al_streak_exists":true,"al_emergency":true,"al_freeze_count":{"param":"CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT","mas":0},"al_freeze_denied":false,"al_excess_freeze_allowed":false},"esperado":true},{"casuistica":"BAJO_EL_LIMITE","entrada":{"al_gamification":true,"al_cannot_hide_or_disable":false,"al_financial_penalty":false,"al_functional_penalty":false,"al_streak_exists":true,"al_emergency":true,"al_freeze_count":{"param":"CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT","mas":-1},"al_freeze_denied":true,"al_excess_freeze_allowed":true},"esperado":true},{"casuistica":"EN_EL_LIMITE","entrada":{"al_gamification":true,"al_cannot_hide_or_disable":false,"al_financial_penalty":false,"al_functional_penalty":false,"al_streak_exists":true,"al_emergency":true,"al_freeze_count":{"param":"CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT","mas":0},"al_freeze_denied":true,"al_excess_freeze_allowed":true},"esperado":true},{"casuistica":"SOBRE_EL_LIMITE","entrada":{"al_gamification":true,"al_cannot_hide_or_disable":false,"al_financial_penalty":false,"al_functional_penalty":false,"al_streak_exists":true,"al_emergency":true,"al_freeze_count":{"param":"CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT","mas":1},"al_freeze_denied":true,"al_excess_freeze_allowed":true},"esperado":true}]},"hash_paquete":"5b3b8d0a31b01296f2252398564035bef5aba1f4f2f7eb8010a3ca9666dc2642","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 IF lf_ops.nucleo_param_valor_v1('UX.SKELETON_SHOW_AFTER_MS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='SKELETON_SHOW_AFTER_MS' AND hecho='al_duration_ms') THEN RAISE EXCEPTION 'S22AL_PARAM_PREFLIGHT UX.SKELETON_SHOW_AFTER_MS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='GAMIFICATION_EMERGENCY_FREEZE_LIMIT' AND hecho='al_freeze_count') THEN RAISE EXCEPTION 'S22AL_PARAM_PREFLIGHT CLIENT.GAMIFICATION_EMERGENCY_FREEZE_LIMIT'; END IF;
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-26 01:50 Lima: Revisado conforme; 182 gemelos HOME/PAYMENTS, 358 HOME, exclusiones aceptadas; juicio V3 independiente');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22AL_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22AL_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22AL_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22AL_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22AL_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-26 01:50 Lima'),h,'GPT / Claude S22-AL independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22AL_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22AL_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22AL_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22AL_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $al$;
COMMIT;
